// AI-generated with Claude Opus 5.5, 2026-10-05, prompted by AhnJinYoung, reviewed by Jaehyun0320 in #50
// A font file imported by a module is the number Metro gives the asset.
declare module '*.otf' {
  const source: number;
  export default source;
}

// A picture imported by a module is an image source.
declare module '*.png' {
  const source: number;
  export default source;
}

declare module '*.jpg' {
  const source: number;
  export default source;
}
